import{c as a,Q as i,j as s,m as l}from"./chunks/framework.DK3sgdKX.js";const k=JSON.parse('{"title":"编辑器架构边界","description":"","frontmatter":{},"headers":[],"relativePath":"EDITOR_ARCHITECTURE.md","filePath":"EDITOR_ARCHITECTURE.md","lastUpdated":1786274880000}'),t={name:"EDITOR_ARCHITECTURE.md"};function n(o,e,d,c,r,p){return i(),s("div",null,[...e[0]||(e[0]=[l(`<h1 id="编辑器架构边界" tabindex="-1">编辑器架构边界 <a class="header-anchor" href="#编辑器架构边界" aria-label="Permalink to &quot;编辑器架构边界&quot;">​</a></h1><p>本文件定义类 Godot 编辑器开发前必须保持的依赖方向。</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Editor panels</span></span>
<span class="line"><span>    ↓ commands</span></span>
<span class="line"><span>Versioned documents</span></span>
<span class="line"><span>    ↓ runtime bridge</span></span>
<span class="line"><span>EngineSession</span></span>
<span class="line"><span>    ↓</span></span>
<span class="line"><span>Runtime / renderer / resource service</span></span></code></pre></div><h2 id="项目与路径" tabindex="-1">项目与路径 <a class="header-anchor" href="#项目与路径" aria-label="Permalink to &quot;项目与路径&quot;">​</a></h2><ul><li><code>project.pystg.json</code> 标识项目并声明内容目录。</li><li><code>ProjectContext</code> 是项目根路径的唯一发现和解析入口。</li><li>旧代码仍可依赖项目工作目录；主入口会通过 <code>ProjectContext.activate()</code> 提供兼容。</li><li>新代码不得自行猜测 <code>assets/</code> 相对于当前进程的位置。</li></ul><h2 id="文档" tabindex="-1">文档 <a class="header-anchor" href="#文档" aria-label="Permalink to &quot;文档&quot;">​</a></h2><ul><li>所有作者资源使用 <code>*.pystg.json</code>，由文档内的 <code>type</code> 区分 <code>pystg.scene</code>、<code>pystg.pattern</code>、<code>pystg.ui</code> 和 <code>pystg.background</code>。</li><li>公共资源头、引用、迁移、坐标和时间契约见 <a href="./AUTHORING_RESOURCE_CONTRACTS"><code>AUTHORING_RESOURCE_CONTRACTS.md</code></a>。</li><li>文档、节点和时间轴事件都有稳定 UUID。</li><li><code>DocumentStore</code> 只允许读写项目目录内文件，并使用原子替换保存。</li><li>新 schema 必须提供迁移函数和 round-trip 测试。</li><li>复杂的 Python 行为暂不反向解析；以后由 <code>ScriptNode</code> 作为明确的代码扩展点。</li></ul><h2 id="运行时" tabindex="-1">运行时 <a class="header-anchor" href="#运行时" aria-label="Permalink to &quot;运行时&quot;">​</a></h2><ul><li><code>EngineSession</code> 持有一次游戏或预览会话的资源生命周期。</li><li>编辑器不得直接从窗口部件创建全局资源 manager。</li><li>预览必须复用正式运行时渲染路径；模拟预览只能标记为实验性。</li><li>高密度子弹继续留在 NumPy/Numba 池中，不能展开成编辑器场景节点。</li></ul><h2 id="资源" tabindex="-1">资源 <a class="header-anchor" href="#资源" aria-label="Permalink to &quot;资源&quot;">​</a></h2><ul><li><code>ResourceTypeRegistry</code> 是版本化作者资源的 loader、validator、editor、compiler 和 preview contribution 入口；编辑器外壳不得按资源类型增加编译分支。</li><li><code>ResourceService</code> 继续负责当前运行时纹理目录和富编辑纹理兼容模型。</li><li><code>TextureAssetManager</code> 是当前正式运行时纹理目录。</li><li><code>UnifiedTextureManager</code> 暂作为富编辑类型兼容模型，由 <code>ResourceService.editor</code> 管理。</li><li>两种内部表示迁移完成前，关键资源必须通过契约测试证明解析结果一致。</li></ul><h2 id="坐标与时间" tabindex="-1">坐标与时间 <a class="header-anchor" href="#坐标与时间" aria-label="Permalink to &quot;坐标与时间&quot;">​</a></h2><ul><li>作者画布使用固定逻辑像素，基准尺寸为 <code>384x448</code>，原点在左上，Y 向下。</li><li>正式运行时坐标以画面中心为原点，X/Y 范围均为 <code>[-1, 1]</code>，Y 向上。</li><li>编辑器、文档编译器和预览只能通过 <code>CoordinateSpace</code> 做两者转换。</li><li>文档时间存储为声明 tick rate 下的非负整数帧；第一版 tick rate 为 60Hz。</li><li>秒和拍仅为显示/输入单位，通过 <code>Timebase</code> 转换，不以浮点秒作为时间轴主键。</li></ul><h2 id="编辑操作" tabindex="-1">编辑操作 <a class="header-anchor" href="#编辑操作" aria-label="Permalink to &quot;编辑操作&quot;">​</a></h2><ul><li>Inspector、场景树和时间轴修改必须经过 <code>CommandStack</code>，以支持 Undo/Redo。</li><li>编辑器配置应使用 <code>atomic_write_json</code>，避免保存中断导致文件损坏。</li><li>旧弹幕脚本生成器只能导出当前 async API 代码，不能宣称能无损导入任意 Python。</li></ul><h2 id="合入门槛" tabindex="-1">合入门槛 <a class="header-anchor" href="#合入门槛" aria-label="Permalink to &quot;合入门槛&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compileall</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> main.py</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> src</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> game_content</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -m</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pytest</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -q</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tools/validate_assets.py</span></span></code></pre></div><p>此外还需实际启动主游戏、真实符卡预览和主要编辑器窗口。自动测试通过不等于视觉验收通过。</p>`,18)])])}const u=a(t,[["render",n]]);export{k as __pageData,u as default};
